import json,copy
d=json.load(open("requirements.json"))
for rule in ["one-holder-per-resource","never-merge-unapproved"]:
    x=copy.deepcopy(d)
    def strip(l):
        for e in l["edges"]:
            if rule in e.get("rules",[]):
                e["rules"].remove(rule)
                if not e["rules"]: del e["rules"]
        for n in l["nodes"]:
            if "opens" in n: strip(n["opens"])
    strip(x["level"])
    json.dump(x,open(f"requirements-unguarded-{rule}.json","w"),indent=1)
